\label{trapping}
    Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Let the initial data $(z_j(\tau_0), w_j(\tau_0))$ for $2\le j\le \lceil \beta \rceil$ be given. If $(z_2(\tau_0), \dots, z_{\lfloor \beta \rfloor}(\tau_0); w_2(\tau_0),\dots, w_{\lfloor \beta \rfloor} (\tau_0)) \in I^{\lfloor \beta \rfloor} $,    
   then the following holds
    \begin{equation}\label{3.38}
        |(z_j(\tau),w_j(\tau)) |\leq C\Big( e^{-g_2 (\tau-\tau_0)}+(\lceil \beta \rceil-\lfloor\beta\rfloor)e^{-k_{\lceil \beta \rceil} (\tau-\tau_0)} \Big)\ \text{ for any } j\in\{2, \dots, \lceil \beta \rceil\}\text{ and }\tau\geq\tau_0.
    \end{equation}
    Otherwise, there exists a $j\in\{2, \dots, i\}$ such that
    \begin{equation}
        z_j\to \infty \ \text{ as } \ \tau\to\infty.
    \end{equation}

\label{remark 3.7}
    This proposition implies that, in order to achieve asymptotic stability, the initial data must satisfy the finite-dimensional constraints, 
    imposed by the higher order boundary constraints as stated in \eqref{boundary condition}. The number of the constraints is $\lfloor \beta+1 \rfloor$: $\lfloor \beta \rfloor - 1$ are from the higher order constraints in $I^{\lfloor \beta\rfloor}$ and the remaining two are from $z_1=w_1=0$ related to the time translation symmetry.

For $\mu\notin \mathfrak S$, there is no need to impose the constraints at the order $i=\lceil \beta \rceil$ since $k_{\lceil \beta \rceil}>0$. Consequently, competition in the decay rates arises between $g_2$ and $k_{\lceil \beta \rceil}$ whose relative magnitudes are undetermined; in particular, either quantity may dominate depending on $\gamma$ and $\mu$. For notational convenience, we denote 
    \begin{equation}\label{g0}
        \mathtt{a_0} = \min\{g_2, (\lfloor\beta\rfloor-\lceil\beta\rceil +1)g_2  +  (\lceil\beta\rceil -\lfloor\beta\rfloor)k_{\lceil \beta \rceil}\} 
    \end{equation} so that $\mathtt{a_0}= g_2$ if $\mu \in \mathfrak S$ and $\mathtt{a_0}=k_{\lceil \beta \rceil} $ if $\mu\notin \mathfrak S$. 
  The inequality \eqref{3.38} can be written as 
  \begin{equation}
        |(z_j,w_j)| \leq C e^{-\mathtt{a_0}\tau}.
  \end{equation}

\label{weighted L^2 estimates}
	Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Consider smooth solutions $(Z,W)$ to the transport equations \eqref{linear PDE of tilde z w} satisfying $(\partial_y^j Z,\partial_y^jW)|_{(\tau,0)} =0$ for all $\tau\in [\tau_0,\tau_1]$ and $0\le j\le {\bf{n}_{\mu}}-1$. 
	Then there exist constants $b_0 >0$ and $\varepsilon_0>0$  such that for all $b\ge b_0$ the following holds
	\begin{equation}\begin{aligned}
		\frac12\partial_\tau(\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 + b \left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2) \leq -\sigma^2 (\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 +b  \left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2) + \left| \langle \frac{F_1}{y^{{\bf{n}_{\mu}}}},\frac{Z}{y^{{\bf{n}_{\mu}}}} \rangle\right|  + b \left| \langle \frac{F_2}{y^{{\bf{n}_{\mu}}}},\frac{W}{y^{{\bf{n}_{\mu}}}} \rangle\right|  
	\end{aligned}\end{equation}
	where 
	\[
		0< \sigma^2 = (1-\mu){\bf{n}_{\mu}}-\frac32+\frac{\mu}{2}- \epsilon_0.
	\]

\label{linear H^n estimates}
Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Consider smooth solutions $(Z,W)$ where $(\partial_y^j Z,\partial_y^jW)|_{(\tau,0)} =0$ for all $\tau\in [\tau_0,\tau_1]$ and $0\le j\le {\bf{n}_{\mu}}-1$ to the transport equations \eqref{linear PDE of tilde z w}. 
	Then there exist constants $b_1 >0$ and $\varepsilon_1>0$  such that for all $b\ge b_1$ the following holds
\begin{equation}\begin{aligned}
\begin{split}
	\frac12\partial_\tau \Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+b \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 \Big)
	&\le  -\nu^2 \Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+ b\left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}} ^2\Big) +C (\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 + b\left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2) \\
    &\quad +\left|\langle \partial_y^{\bf{n}_{\mu}} F_1, \partial_y^{\bf{n}_{\mu}} Z \rangle \right| +b \left|\langle \partial_y^{\bf{n}_{\mu}} F_2, \partial_y^{\bf{n}_{\mu}} W \rangle \right|                                 
\end{split}
\end{aligned}\end{equation}	
where  $C=C(\varepsilon_1)>0$ is a constant and 
\[
0 < \nu^2 =  (1-\mu){\bf{n}_{\mu}} - \frac32 + \frac{\mu}{2}  -  \varepsilon_1.
\]

We take the $L^2$ inner product of \eqref{linear PDE of der of tilde z w} with $(\partial_y^{\bf{n}_{\mu}} Z, b  \partial_y^{\bf{n}_{\mu}} W )$ and integrate by parts to obtain 
 \begin{align*}
 	&\frac12\partial_\tau \Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+ b \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 \Big)\\
	&= -\int_0^\infty \Big(({\bf{n}_{\mu}}+\tfrac12) (1+\tfrac{(\gamma+1)}{4}\partial_y \mathring z)+\mu- 2 \Big) |\partial_y^{{\bf{n}_{\mu}}} Z|^2  dy -b \int_0^\infty \Big(({\bf{n}_{\mu}}-\tfrac12)(1+\tfrac{(3-\gamma)}{4}\partial_y\mathring z) +\mu- 1 \Big) | \partial_y^{{\bf{n}_{\mu}}} W|^2  dy   \\
	&- \int_0^\infty \tfrac{3-\gamma}{4} \partial_y \mathring z \partial_y^{\bf{n}_{\mu}} W \partial_y^{\bf{n}_{\mu}} Z dy  - \int_0^\infty \Bigg( \tfrac{3-\gamma}{4} \sum_{i=0}^{{\bf{n}_{\mu}}-1}\binom{{\bf{n}_{\mu}}}{i}\partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z  \partial_y^i W  +\tfrac{\gamma+1}{4}\sum_{i=0}^{{\bf{n}_{\mu}}-1} \binom{{\bf{n}_{\mu}}+1}{i} \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i Z  
    \Bigg)\partial_y^{{\bf{n}_{\mu}}} Z \ dy  \\
	&-b \int_0^\infty \tfrac{3-\gamma}{4}\sum_{i=1}^{{\bf{n}_{\mu}}-1} \binom{{\bf{n}_{\mu}}}{i-1} \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^{i} W \partial_y^{{\bf{n}_{\mu}}} W \ dy +\int_0^\infty \partial_y^{\bf{n}_{\mu}} F_1  \partial_y^{\bf{n}_{\mu}}Z \ dy +b \int_0^\infty \partial_y^{\bf{n}_{\mu}} F_2  \partial_y^{\bf{n}_{\mu}}W \ dy \\
    &=: (I) + (II) + (III)
\end{align*}
We estimate $(I), \ (II), \ (III)$ in what follows. For $(I)$, using $-\frac{4\mu}{\gamma+1} \le\partial_y \mathring z < 0$ from Proposition \ref{prop bar z}, we have  
\begin{align*}
(I) \le - ({\bf{n}_{\mu}} (1-\mu) + \tfrac{\mu}{2} - \tfrac32) \int_0^\infty |\partial_y^{\bf{n}_{\mu}} Z|^2 dy 
-  ( {\bf{n}_{\mu}}(1- \mu) + \tfrac32 
\mu  -\tfrac32 ) b \int_0^\infty |\partial_y^{\bf{n}_{\mu}} W|^2 dy
\end{align*}
The first term of $(II)$ can be bounded by 
\[
\left| \int_0^\infty \tfrac{3-\gamma}{4} \partial_y \mathring z \partial_y^{\bf{n}_{\mu}} W \partial_y^{\bf{n}_{\mu}} Z dy \right| \le \varepsilon_0  \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 + C_{\varepsilon_0} \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2
\]
where $\varepsilon_0>0$ is to be determined. 
To handle the rest of commutator terms in $(II)$ and $(III)$, we first estimate   
\begin{align*}
    \sum_{i=0}^{{\bf{n}_{\mu}}-1}{\int_0^\infty\Big( \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i Z\Big)^2 \ dy} =:  {\sum_{i=0}^{{\bf{n}_{\mu}}-1} S_z^i} =: S_z 
 \end{align*}
By applying Proposition \ref{prop: mathring z}, $\mathring z$ has different behavior in the different regions of $y$ for each $0\le i\le {\bf{n}_{\mu}}-1$. Consequently, we decompose $S_z^i$ into two integrals: 
 \begin{align*}
 	S_z^i = \int_0^{y_*} \Big( \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i Z\Big)^2 \ dy 
	+  \int_{y_*}^{2y_0e^{\tau-\tau_0}} \Big( \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i Z\Big)^2 \ dy := S_{z,1}^i+S_{z,2}^i 
 \end{align*}
 where $y_*$ is small and to be determined. 
For $S_{z,1}^i$, we separate into two cases: $\mu\in \mathfrak S$ and $\mu\notin \mathfrak S$. 
When $\mu\in\mathfrak S$, as in Proposition  \ref{prop bar z} (3), $\partial_y \mathring z$ and $\partial_y^{ \beta } \mathring z $ are only bounded for small $y$. By using Hardy inequality (cf. Lemma \ref{hardy 1}), we have 
 \begin{equation}\label{Sz1}
 	S_{z,1}^i \le  C \int_0^{y_*} | \partial_y^i Z|^2 \ dy \le C  y_\ast^{2({\bf{n}_{\mu}}-i)}  \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2.
 \end{equation}
 When $\mu\notin \mathfrak S$, we estimate 
\begin{equation}\label{Sz1-2}
 	S_{z,1}^i \leq C\int_0^{y_*} \Big( y^{\beta - {\bf{n}_{\mu}} -1 +i}\partial_y^i Z\Big)^2 \ dy = C\int_0^{y_*} \Big( y^{\beta -1}\frac{\partial_y^i Z}{y^{{\bf{n}_{\mu}}-i}}\Big)^2 \ dy \leq C y_\ast^{2(\beta-1)}  \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2
 \end{equation}
 where we have used $\beta>1 $. In both cases, we conclude that $ S_{z,1}^i \le  C y_* \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2$. 
Now for $S_{z,2}^i$, we use Proposition \ref{prop: mathring z} and  Lemma \ref{G-N with weight} 
to bound for $0\le i\le {\bf{n}_{\mu}}-1$
 \begin{equation}\begin{aligned}\label{Sz3}
 	 \int_{y_*}^{2y_0e^{\tau-\tau_0}} \Big( \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i Z\Big)^2 \ dy &\leq C \int_{y_*}^{2y_0e^{\tau-\tau_0}} \Big( y^{-\mu-{\bf{n}_{\mu}}+i}\partial_y^i Z\Big)^2 \ dy \le C_* \left\lVert\frac{Z}{y^{\bf{n}_{\mu}}}\right\rVert_{L^2}^{2- \frac{2i}{{\bf{n}_{\mu}}}} \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^{\frac{2i}{{\bf{n}_{\mu}}}} 
 \end{aligned}\end{equation}
 where $C_*$ depends on $y_*$.  
Hence, we deduce that 
 \begin{equation}\label{Sz}
 	S_z  \leq C y_*   \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 + C_* \sum_{i=0}^{{\bf{n}_{\mu}}-1} \left\lVert\frac{Z}{y^{\bf{n}_{\mu}}}\right\rVert_{L^2}^{2- \frac{2 i}{{\bf{n}_{\mu}}}} \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^{\frac{2i}{{\bf{n}_{\mu}}}}. 
\end{equation}
Similarly, we can derive 
  \begin{equation}\label{Sw}
 	\sum_{i=0}^{{\bf{n}_{\mu}}-1}  \int_0^\infty\Big(  \partial_y^{{\bf{n}_{\mu}}+1-i} \mathring z \partial_y^i W\Big)^2 \ dy \leq  C y_*   \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 + C_* \sum_{i=0}^{{\bf{n}_{\mu}}-1}  \left\lVert\frac{W}{y^{\bf{n}_{\mu}}}\right\rVert_{L^2}^{2- \frac{2 i}{{\bf{n}_{\mu}}}} \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^{\frac{2i}{{\bf{n}_{\mu}}}}. 
 \end{equation}
By putting the estimates together and using Young's inequality, we arrive at  
 \begin{align*}
 	&\frac12\partial_\tau \Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+ b \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 \Big)\\
	&\le - ({\bf{n}_{\mu}} (1-\mu) + \tfrac{\mu}{2} - \tfrac32 -\varepsilon_0 - C y_* - C_*\varepsilon ) \int_0^\infty |\partial_y^{\bf{n}_{\mu}} Z|^2 dy 
\\
&\quad -  ( {\bf{n}_{\mu}}(1- \mu) + \tfrac32 
\mu  -\tfrac32 - \tfrac{C_{\varepsilon_0}}{b} - \tfrac{C y_*}{b} - C_*\varepsilon ) b \int_0^\infty |\partial_y^{\bf{n}_{\mu}} W|^2 dy \\
& \quad + C_{*, \varepsilon} \Big(  \left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 + b  \left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2\Big) + \left|\langle \partial_y^{\bf{n}_{\mu}} F_1, \partial_y^{\bf{n}_{\mu}} Z \rangle \right| +b \left|\langle \partial_y^{\bf{n}_{\mu}} F_2, \partial_y^{\bf{n}_{\mu}} W \rangle \right|
\end{align*}
  Recall the definition of ${\bf{n}_{\mu}}$ in \eqref{def ndmu}. We may choose $\varepsilon_0>0$, $y_*>0$ and $\varepsilon>0$ small so that 
  \[
 {\bf{n}_{\mu}} (1-\mu) + \tfrac{\mu}{2} - \tfrac32 -\varepsilon_0 - C y_* - C\varepsilon >0  
    \]
Then for sufficiently large $b>0$,  
    \[
    {\bf{n}_{\mu}}(1- \mu) + \tfrac32 
\mu  -\tfrac32 - \tfrac{C_{\varepsilon_0}}{b} - \tfrac{C y_*}{b} - C_*\varepsilon \ge {\bf{n}_{\mu}} (1-\mu) + \tfrac{\mu}{2} - \tfrac32 -\varepsilon_0 - C y_* - C_*\varepsilon >0  
    \]
    which implies the desired energy inequality.

\label{bootstrap lemma}
	Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Assume that initial modulation variables satisfy \eqref{initialziwi}. 
	Then there exist $y_0=e^{\tau_0}$, and $\sigma_0,\mathtt{a_0},\mathtt{a_1}, \mathtt{a_2} >0$ 
    such that
	\begin{equation}\label{sequence a_1, a_2, a_0}
		0< \mathtt{a_2}<\mathtt{a_1}<\min\{\frac{(4\mu-1)(1-\mu)}{2}, \frac{2(1-\mu){\bf{n}_{\mu}}-3+\mu}{6},\mathtt{a_0}\}
	\end{equation}
	the following holds. 
    Assume that there exists a solution 
    $(Z, W)\in H^{\bf{n}_{\mu}} $ 
     to the
	the system \eqref{full system Z W} 
	on $[\tau_0,\tau_1]$, satisfies 
	and the bootstrap assumption
	\begin{align}
		\left\lVert(Z, W)\right\rVert_{\dot H^{\bf{n}_{\mu}}}+\left\lVert(\frac{Z}{y^{\bf{n}_{\mu}}},\frac{W}{y^{\bf{n}_{\mu}}})\right\rVert_{L^2}\leq 2e^{-\mathtt{a_1} \tau}\ \text{ and }\tau\in[\tau_0,\tau_1],\\
        \left\lVert(\partial_yZ, \partial_yW)\right\rVert_{L^2} \leq 2Be^{-(\mu-\frac12)\mathtt{a_2} \tau}\ \text{ and }\tau\in[\tau_0,\tau_1],\\
		\left\lVert(Z,W)\right\rVert_{L^2} \leq 2Be^{(\frac32-\mu)\tau} \ \text{ and }\tau\in[\tau_0,\tau_1]. 
	\end{align}
	Then, for $\tau_0$ sufficiently large and $\left\lVert(Z(\tau_0,\cdot), W(\tau_0,\cdot))\right\rVert_{H^{\bf{n}_{\mu}}}\leq \sigma_0$, we have the following improvement of the bootstrap assumptions:
	\begin{align}
		\left\lVert(Z, W)\right\rVert_{\dot H^{\bf{n}_{\mu}}}+\left\lVert(\frac{Z}{y^{\bf{n}_{\mu}}},\frac{W}{y^{\bf{n}_{\mu}}})\right\rVert_{L^2} \leq e^{-\mathtt{a_1} \tau}\ \text{ and }\tau\in[\tau_0,\tau_1],\label{payn z w}\\
        \left\lVert(\partial_yZ, \partial_yW)\right\rVert_{L^2} \leq Be^{-(\mu-\frac12)\mathtt{a_2} \tau}\ \text{ and }\tau\in[\tau_0,\tau_1]\label{pay z w},\\
		\left\lVert(Z,W)\right\rVert_{L^2} \leq Be^{(\frac32-\mu)\tau} \ \text{ and }\tau\in[\tau_0,\tau_1]\label{L2}. 
	\end{align}

\label{prop payi mz mw}
	Let $\gamma\in(1,3)$ and $\mu\in[\frac12, 1)$. 
    Assume that initial modulation variables satisfy \eqref{initialziwi}. Then for $i\in\{0,1,\dots,{\bf{n}_{\mu}}+1\}$ and $p\in[1,\infty]$, we have 
	\begin{equation}
		\left\lVert\frac{M_z}{y}\right\rVert_{L^p}+\left\lVert\frac{M_w}{y}\right\rVert_{L^p}+\left\lVert \partial_y^i M_z\right\rVert_{L^p}+\left\lVert\partial_y^i M_w \right\rVert_{L^p} \leq Ce^{-\mathtt{a_0} \tau} 
	\end{equation}
	where $\mathtt{a_0}$ is defined in \eqref{g0} and $C=:C(\gamma,\mu)$ is a positive constant.

We begin by recalling the definitions of $M_z$ and $M_w$ from \eqref{def mz mw}. A direct computation yields
    \begin{align*}
        \frac{M_z}{y} &= \sum_{j=2}^{{\bf{n}_{\mu}}-1}  \frac{z_j(\tau)}{j!}\varphi(y)y^{j-1},\\
        \partial_y^iM_z &= \sum_{j=2}^{{\bf{n}_{\mu}}-1}  \frac{z_j(\tau)}{j!}\partial_y^i(\varphi(y)y^j) = \sum_{j=2}^{{\bf{n}_{\mu}}-1}  \sum_{\ell=0}^{\min \{i,j\}} c_{i\ell }\frac{z_j(\tau)}{j!}\partial_y^{i-\ell}\varphi(y)y^{j-\ell}.
    \end{align*}
    Since $\varphi$ is compactly supported and using Proposition \ref{trapping}, we have
    \[
       \left\lVert\frac{M_z}{y}\right\rVert_{L^p}+ \left\lVert\partial_y^iM_z\right\rVert_{L_p} \leq C \sum_{j=2}^{{\bf{n}_{\mu}}-1}  | z_j(\tau) | \leq C e^{-\mathtt{a_0} \tau} 
    \]
    where $C$ is a constant depending on ${\bf{n}_{\mu}}$. The corresponding estimates for $M_w$ follow analogously.

\label{prop Tz Tw /y}
Let $\gamma\in(1,3)$ and $\mu\in[\frac12, 1)$. 
Assume that initial modulation variables satisfy \eqref{initialziwi}. Then for $i\in\{0,1,\dots,{\bf{n}_{\mu}}\}$, we have 
    \begin{equation}
        \left\lVert (\partial_y^i\mathcal T_z,\partial_y^i\mathcal T_w)\right\rVert_{L^2} +\left\lVert( \frac{\mathcal T_z}{y^{{\bf{n}_{\mu}}}}, \frac{\mathcal T_w}{y^{{\bf{n}_{\mu}}}} )\right\rVert_{L^2}\le C e^{-\mathtt{a_0} \tau}
    \end{equation}
    where $\mathtt{a_0}$ is defined in \eqref{g0} and $C=:C(\gamma,\mu)$ is a positive constant.

\label{estimate of Schi}
	Let $\gamma\in(1,3)$ and $\mu\in [\frac12,1)$.
    Then,
	\begin{equation}\begin{aligned}
		 \int_0^\infty (\partial_y^i\big(  \bar z (1-\chi) \partial_y \mathring z\big))^2  \ dy  \leq C y_0^{3-4\mu-2i} e ^{-(1-\mu)(2i +4\mu -3) (\tau-\tau_0)}, 
	\end{aligned}\end{equation}
	for each $1\le i\le {\bf{n}_{\mu}}$.

\label{ode Hn}
	Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Under the assumptions of Proposition  \ref{bootstrap lemma}, there exist $C:=C(\gamma,\mu)>0$ and $b>0$ such that
	\begin{equation}\begin{aligned}\label{Hn ineq}
		 &\frac12\partial_\tau \Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+b \left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 +  C(\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 + b\left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2) \Big)\\
	&\le   -\frac{1}{2}\Big((1-\mu){\bf{n}_{\mu}} - \frac32 + \frac{\mu}{2} \Big)\Big( \left\lVertZ\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+ b\left\lVertW\right\rVert_{\dot H^{{\bf{n}_{\mu}}}} ^2 +C (\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2 + b\left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2\Big) \\
    &+C y_0^{\frac32-2\mu-{\bf{n}_{\mu}}} e ^{-(1-\mu)({\bf{n}_{\mu}} +2\mu -\frac{3}{2}) (\tau-\tau_0)} e^{-\mathtt{a_1} \tau} +Ce^{-\mathtt{a_0} \tau}e^{-\mathtt{a_1} \tau}\\
     &+ CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}e^{-(\mu-\frac12)(1-\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_2}\tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}.
	\end{aligned}\end{equation}

In the following proof, we will use $C$ to denote a generic positive constant that only depends
on ${\bf{n}_{\mu}}$, $\gamma$ and $\mu$. It may vary from line to line.
    From Lemma \ref{weighted L^2 estimates} and Lemma \ref{linear H^n estimates}, it remains to establish  the estimates of $\left| \langle \frac{F_1}{y^{\bf{n}_{\mu}}},\frac{Z}{y^{\bf{n}_{\mu}}} \rangle\right|$,  $\left| \langle \frac{F_2}{y^{\bf{n}_{\mu}}},\frac{W}{y^{\bf{n}_{\mu}}} \rangle\right| $ , $\left|\langle \partial_y^{\bf{n}_{\mu}} F_1, \partial_y^{\bf{n}_{\mu}} Z \rangle \right|$, and $ \left|\langle \partial_y^{\bf{n}_{\mu}} F_2, \partial_y^{\bf{n}_{\mu}} W \rangle \right|$. Here $F_1= \mathcal S_z - \mathcal N_z - \mathcal T_z$ and $F_2= - \mathcal N_w - \mathcal T_w$ where $\mathcal S_z$, $\mathcal N_z$, $\mathcal T_z$, $\mathcal N_w$ and $\mathcal T_w$ are defined in \eqref{nz nmz}. 
    Since the estimation corresponding to $F_2$ is the same as the one to $F_1$, we will only present the estimation of $\left|\langle \partial_y^{\bf{n}_{\mu}} F_1, \partial_y^{\bf{n}_{\mu}} Z \rangle \right|$ and $\left| \langle \frac{F_1}{y^{\bf{n}_{\mu}}},\frac{Z}{y^{\bf{n}_{\mu}}} \rangle\right|$. 

	\noindent\underline{The source term $\mathcal S_z$}:
    First of all, $\partial_y^j\mathcal S_z(\tau,0)=0$ for any $j\geq 0$ since it has a compact support away from $y=0$. Hence, by Lemma \ref{hardy 1}, 
    \[
        \left\lVerty^{-{\bf{n}_{\mu}}}\mathcal S_z\right\rVert_{L^2} \leq C\left\lVert\partial_y^{{\bf{n}_{\mu}}}\mathcal S_z\right\rVert_{L^2}.
    \]
    It then follows that
    \[
    \begin{split}
      \Big|  \int_0^\infty \frac{\mathcal S_z}{y^{{\bf{n}_{\mu}}}} \frac{Z}{y^{{\bf{n}_{\mu}}}} \ dy \Big| + \Big|\int_0^\infty \partial_y^{\bf{n}_{\mu}}\mathcal S_z \partial_y^{\bf{n}_{\mu}} Z \ dy \Big| 
       &\leq C\left\lVert\partial_y^{\bf{n}_{\mu}}\mathcal S_z\right\rVert_{L^2}\left\lVert\partial_y^{\bf{n}_{\mu}} Z\right\rVert_{L^2} \\
       & \leq C {y_0^{\frac32-2\mu-{\bf{n}_{\mu}}}}e ^{-(1-\mu)({\bf{n}_{\mu}} +2\mu -\frac{3}{2}) (\tau-\tau_0)} e^{-\mathtt{a_1} \tau}.
   \end{split}
    \]
    where we have used Young's inequality in the first step, Lemma \ref{estimate of Schi}, and the bootstrap assumption in Proposition \ref{bootstrap lemma} in the last step. 

	\noindent\underline{The nonlinear term $\mathcal N_z$}: 
    For the weighted $L^2$ estimates, we proceed as 
    \begin{align*}
      & \Big| \int_0^\infty \frac{\mathcal N_z}{y^{{\bf{n}_{\mu}}}} \frac{Z}{y^{{\bf{n}_{\mu}}}} \ dy \Big| = \Big|\frac{\gamma+1}{4}\int_0^\infty(\partial_yZ+\partial_yM_z) (\frac{Z}{y^{{\bf{n}_{\mu}}}})^2 \ dy +\frac{3-\gamma}{4}\int_0^\infty (\partial_y Z+\partial_y M_z)\frac{Z W}{y^{2{\bf{n}_{\mu}}}} \ dy\\
        &\qquad\qquad\qquad\qquad\quad + \int_0^1(\frac{\gamma+1}{4}\frac{M_z}{y} +\frac{3-\gamma}{4}\frac{M_w}{y} ) \frac{\partial_y Z}{y^{{\bf{n}_{\mu}}-1}}\frac{ Z}{y^{{\bf{n}_{\mu}}}} \ dy\Big| \\
       & \leq C\Big( \left\lVert\frac{M_z}{y}\right\rVert_{L^\infty}+\left\lVert\frac{M_w}{y}\right\rVert_{L^\infty}+\left\lVert\partial_yM_z\right\rVert_{L^\infty}+\left\lVert\partial_yZ\right\rVert_{L^\infty}\Big) (\left\lVert\frac{\partial_y Z}{y^{{\bf{n}_{\mu}}-1}}\right\rVert_{L^2}^2+\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2+\left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}^2)\\
       &\leq C\Big(e^{-\mathtt{a_0} \tau}++B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}e^{-(\mu-\frac12)(1-\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_2}\tau} e^{-\frac{1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1} \tau}\Big) e^{-2\mathtt{a_1} \tau}
    \end{align*}
    where we have used Proposition \ref{prop payi mz mw}, Lemma \ref{hardy 1}, Lemma \ref{Linfty decay}, and the bootstrap assumption in Proposition \ref{bootstrap lemma} in the last inequality.
    For the $\dot H^{{\bf{n}_{\mu}}}$ estimates,
	\begin{align*}
	    \int_0^\infty \partial_y^{{\bf{n}_{\mu}}}\mathcal N_z \partial_y^{{\bf{n}_{\mu}}} Z dy&= \sum_{i=0}^{{\bf{n}_{\mu}}} c_{{\bf{n}_{\mu}} i} \int_0^\infty (\frac{\gamma+1}{4}\partial_y^iM_z+\frac{3-\gamma}{4}\partial_y^iM_w+\frac{\gamma+1}{4}\partial_y^iZ+\frac{3-\gamma}{4}\partial_y^iW)\partial_y^{{\bf{n}_{\mu}}+1-i}Z\partial_y^{{\bf{n}_{\mu}}} Z dy\\
        &+\sum_{i=0}^{{\bf{n}_{\mu}}} c_{{\bf{n}_{\mu}} i} \int_0^\infty \partial_y^{{\bf{n}_{\mu}}+1-i}M_z(\frac{\gamma+1}{4}\partial_y^iZ +\frac{3-\gamma}{4}\partial_y^iW)\partial_y^{{\bf{n}_{\mu}}}Z \ dy\\
        &=: I+II.
	\end{align*}
	We first obtain an estimate of $I$ by considering three cases, depending on the value of $i$. 
	When $i=0$, by integrating by parts, we obtain
	\begin{align*}
		 &\Big|\int_0^\infty (\frac{\gamma+1}{4}M_z+\frac{3-\gamma}{4}M_w+\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4}W)\partial_y^{{\bf{n}_{\mu}}+1}Z\partial_y^{\bf{n}_{\mu}} Z dy\Big| \\
		 \leq&\frac12 \int_0^\infty |\frac{\gamma+1}{4}\partial_yM_z+\frac{3-\gamma}{4}\partial_yM_w+\frac{\gamma+1}{4}\partial_yZ+\frac{3-\gamma}{4}\partial_yW|\mid\partial_y^{\bf{n}_{\mu}} Z\mid^2 dy \\
		 \leq & C\Big(\left\lVert\partial_yM_z\right\rVert_{L^\infty}+\left\lVert\partial_yM_w\right\rVert_{L^\infty} +\left\lVert\partial_yZ\right\rVert_{L^\infty}+\left\lVert\partial_yW\right\rVert_{L^\infty}\Big) \left\lVert\partial_y^{\bf{n}_{\mu}}Z\right\rVert_{L^2}^2\\
		 \leq &  C\Big(e^{-\mathtt{a_0} \tau}+B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}e^{-(\mu-\frac12)(1-\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_2}\tau} e^{-\frac{1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1} \tau}\Big) e^{-2\mathtt{a_1} \tau}
	\end{align*}
	where we used Proposition \ref{prop payi mz mw}, Lemma \ref{Linfty decay}, and the bootstrap assumption in Proposition \ref{bootstrap lemma} in the last inequality. When $i={\bf{n}_{\mu}}$, 
    \begin{align*}
        &\Big|\int_0^\infty (\frac{\gamma+1}{4}\partial_y^{\bf{n}_{\mu}}M_z+\frac{3-\gamma}{4}\partial_y^{\bf{n}_{\mu}}M_w+\frac{\gamma+1}{4}\partial_y^{\bf{n}_{\mu}}Z+\frac{3-\gamma}{4}\partial_y^{\bf{n}_{\mu}}W)\partial_yZ\partial_y^{{\bf{n}_{\mu}}} Z dy\Big|\\
        \leq & C \left\lVert\partial_y Z\right\rVert_{L^\infty}\big(\left\lVert\partial_y^{{\bf{n}_{\mu}}} M_z\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} M_w\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} Z\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} W\right\rVert_{L^2} \big) \left\lVert\partial_y^{{\bf{n}_{\mu}}} Z\right\rVert_{L^2}\\
        \leq & C \left\lVert\partial_y Z\right\rVert_{L^2}^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}\left\lVert\partial_y^{\bf{n}_{\mu}} Z\right\rVert_{L^2}^{\frac{1}{2({\bf{n}_{\mu}}-1)}}\big(\left\lVert\partial_y^{{\bf{n}_{\mu}}} M_z\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} M_w\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} Z\right\rVert_{L^2}+\left\lVert\partial_y^{{\bf{n}_{\mu}}} W\right\rVert_{L^2} \big) \left\lVert\partial_y^{{\bf{n}_{\mu}}} Z\right\rVert_{L^2}\\
        \leq & CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}
    \end{align*}
    where we have applied Lemma \ref{Linfty decay} in the second inequality, and Proposition \ref{prop payi mz mw}, \eqref{sequence a_1, a_2, a_0}, and the bootstrap assumption in Proposition \ref{bootstrap lemma} in the third inequality. 
	Considering $1\leq i\leq {\bf{n}_{\mu}}-1$, we estimate by using Gagliardo–Nirenberg interpolation inequality and Lemma \ref{Linfty decay}:
	\begin{align}
		&\int_0^\infty |(\partial_y^iM_w+\partial_y^iW)\partial_y^{{\bf{n}_{\mu}}+1-i}Z\partial_y^{\bf{n}_{\mu}} Z | dy\notag \\
        &\leq C (\left\lVert\partial_y^iM_w\right\rVert_{L^\infty}+\left\lVert\partial_y^iW\right\rVert_{L^\infty}) \left\lVert\partial_y^{{\bf{n}_{\mu}}+1-i}Z\right\rVert_{L^2} \left\lVert\partial_y^{\bf{n}_{\mu}} Z\right\rVert_{L^2}\notag\\
		&\leq C (\left\lVert\partial_y^iM_w\right\rVert_{L^\infty}+\left\lVert\partial_y W\right\rVert_{L^2}^{1-\frac{2i-1}{2({\bf{n}_{\mu}}-1)}} \left\lVert\partial_y^{\bf{n}_{\mu}} W\right\rVert_{L^2}^{\frac{2i-1}{2({\bf{n}_{\mu}}-1)}} )\left\lVert\partial_y Z\right\rVert_{L^2}^{1-\frac{{\bf{n}_{\mu}}-i}{{\bf{n}_{\mu}}-1}} \left\lVert\partial_y^{\bf{n}_{\mu}} Z\right\rVert_{L^2}^{\frac{{\bf{n}_{\mu}}-i}{{\bf{n}_{\mu}}-1}} \left\lVert\partial_y^{\bf{n}_{\mu}} Z\right\rVert_{L^2}\notag\\
        &\leq  CB^{\frac{i-1}{{\bf{n}_{\mu}}-1}} e^{-\frac{i-1}{{\bf{n}_{\mu}}-1}(\mu-\frac12)\mathtt{a_2} \tau} e^{-(1+\frac{{\bf{n}_{\mu}}-i}{{\bf{n}_{\mu}}-1})\mathtt{a_1} \tau} e^{-\mathtt{a_0} \tau}+CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}\notag\\
        &\leq CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}\label{est 4.28}
        \end{align}
where we have used $1\leq i \leq {\bf{n}_{\mu}}$, \eqref{sequence a_1, a_2, a_0} and the assumption in Proposition \ref{bootstrap lemma} to obtain the last inequality.
	The remaining two terms can be estimated analogously. Combining these estimates, we obtain
	\begin{align*}
		|I| \leq  e^{-\mathtt{a_0}\tau} e^{-2\mathtt{a_1}\tau}+ CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}.
	\end{align*}
For $II$, when $1\leq i\leq {\bf{n}_{\mu}}$, it can be estimated in the same manner as the first term in \eqref{est 4.28}. For $i=0$, we estimate
\begin{align*}
   \Big| \int_0^\infty\partial_y^{{\bf{n}_{\mu}}+1}M_z (\frac{\gamma+1}{4}Z +\frac{3-\gamma}{4}W)\partial_y^{{\bf{n}_{\mu}}}Z \ dy\Big|  
    &\leq \int_0^1 \Big|\partial_y^{{\bf{n}_{\mu}}+1}M_z(\frac{\gamma+1}{4}\frac{Z}{y^{{\bf{n}_{\mu}}}} +\frac{3-\gamma}{4}\frac{W}{y^{{\bf{n}_{\mu}}}})\partial_y^{{\bf{n}_{\mu}}}Z \Big| \ dy \\
    &\leq C \left\lVert\partial_y^{{\bf{n}_{\mu}}+1}M_z\right\rVert_{L^\infty}(\left\lVert\partial_y^{{\bf{n}_{\mu}}}Z\right\rVert_{L^2}^2+\left\lVert\partial_y^{{\bf{n}_{\mu}}}W\right\rVert_{L^2}^2)\\
    &\leq C e^{-\mathtt{a_0}\tau} e^{-2\mathtt{a_1}\tau}
\end{align*}
where we have used Young's inequality and Lemma \ref{hardy 1} in the second inequality, and the bootstrap assumption in Proposition \ref{bootstrap lemma} to obtain the last inequality. Combining all the estimations above, we derive
\[
     \int_0^\infty \Big| \frac{\mathcal N_z}{y^{{\bf{n}_{\mu}}}} \frac{Z}{y^{{\bf{n}_{\mu}}}}\Big| +| \partial_y^{{\bf{n}_{\mu}}}\mathcal N_z \partial_y^{{\bf{n}_{\mu}}} Z| \ dy  \leq C   e^{-\mathtt{a_0}\tau} e^{-2\mathtt{a_1}\tau}  + CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}.
\]


 	\noindent\underline{The nonlinear term $\mathcal T_z$:} By using H\"{o}lder inequality, we obtain
	\begin{align*}
		\Big| \int_0^\infty \partial_y^{\bf{n}_{\mu}}\mathcal T_z\partial_y^{\bf{n}_{\mu}} Z dy\Big|+\Big|\int_0^\infty \frac{\mathcal T_z}{y^{{\bf{n}_{\mu}}}} \frac{Z}{y^{{\bf{n}_{\mu}}}} dy \Big|
		\le \left\lVert\partial_y^{\bf{n}_{\mu}} \mathcal T_z\right\rVert_{L^2} \left\lVertZ\right\rVert_{\dot H^{\bf{n}_{\mu}}}+\left\lVert\frac{\mathcal T_z^0}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2} \left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}\right\rVert_{L^2}
        \leq C e^{-\mathtt{a_0} \tau} e^{-\mathtt{a_1} \tau}
	\end{align*}
    where we have applied Lemma \ref{prop Tz Tw /y} and the bootstrap assumption in Proposition \ref{bootstrap lemma} in the last step. 
   Combining all the estimations above, choosing $\epsilon_0=\epsilon_1=\frac{1}{2}\big((1-\mu){\bf{n}_{\mu}} - \frac32 + \frac{\mu}{2} \big)$ in Lemma \ref{weighted L^2 estimates} and Lemma \ref{linear H^n estimates}, and using the fact $e^{-\mathtt{a_0} \tau}e^{-2\mathtt{a_1} \tau} \leq e^{-\mathtt{a_0} \tau}e^{-\mathtt{a_1} \tau}$, we arrive at \eqref{Hn ineq}.

\label{lemma nonlinear H^1}
	 Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$. Under the assumptions of Proposition \ref{bootstrap lemma}, there exists a constant $C:=C(\gamma,\mu)>0$ such that
	\begin{align*}
    \partial_\tau\Big(\left\lVert\partial_yZ\right\rVert_{L^2}^2+\left\lVert\partial_yW\right\rVert_{L^2}^2\Big)
			&\leq  -(2\mu-1 ) \Big(\left\lVert\partial_y Z\right\rVert_{L^2}^2 +\left\lVert\partial_y W\right\rVert_{L^2} ^2\Big) + C   e^{-\mathtt{a_1} \tau} + CB^2 e^{-\frac{\mu\mathtt{a_1}}{2({\bf{n}_{\mu}}-1)} \tau }e^{-(2\mu-1)\mathtt{a_2} \tau} \\
          &+CB y_0^{\frac{-4\mu +1}{2}} 
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{-(\mu-\frac12)\mathtt{a_2}\tau}.
		 \end{align*}

From \eqref{full system Z W}, the equations for $(\partial_y Z, \partial_y W)$ read as  
	\begin{equation}\begin{aligned}\label{full system pay Z W}
	\partial_\tau\partial_y Z + (y+\frac{\gamma+1}{4}\mathring z ) \partial_y^{2} Z + (\frac{(\gamma+1)}{2}\partial_y \mathring z+\mu)\partial_yZ +\frac{3-\gamma}{4}\partial_y(\partial_y \mathring z W)
    +\frac{\gamma+1}{4}\partial_y^2 \mathring z Z& \\
+\partial_y\mathcal N_z
+ \partial_y\mathcal T_z& = \partial_y\mathcal S_z,\\
		\partial_\tau \partial_yW + (y+\frac{3-\gamma}{4}\mathring z ) \partial_y^2 W + (\frac{(3-\gamma)}{4}\partial_y \mathring z+\mu)\partial_yW  + \partial_y\mathcal N_w 
        + \partial_y\mathcal T_w & = 0.
\end{aligned}\end{equation}
The energy estimates of \eqref{full system pay Z W} lead to 
\begin{align*}
    \frac12\partial_\tau\Big(\left\lVert\partial_yZ\right\rVert_{L^2}^2+  \left\lVert\partial_yW\right\rVert_{L^2}^2\Big) = I+ II + III
\end{align*}
where
\begin{align*}
	I&= \int_{0}^\infty -\Big(\frac{3(\gamma+1)}{8}\partial_y \mathring z+\mu-\frac{1}{2} \Big) \mid \partial_y Z\mid^2 - \Big(\frac{(3-\gamma)}{8}\partial_y\mathring z+\mu-\frac{1}{2} \Big) \mid \partial_y W\mid^2 \ dy  \\
	II&=-\int_{0}^\infty \Bigg( \frac{3-\gamma}{4}\partial_y\Big(\partial_y \mathring z  W\Big) +\frac{\gamma+1}{4} \partial_y^2 \mathring z  Z
    \Big)  \Bigg)\partial_y Z \ dy \\
	III&=  \int_{0}^\infty \partial_y\mathcal S_z \partial_y Z dy- \int_{0}^\infty \Big( \partial_y\mathcal N_z 
    + \partial_y\mathcal T_z \Big) \partial_y Z dy  - \int_{0}^\infty\Big( \partial_y\mathcal N_w 
    + \partial_y\mathcal T_w\Big) \partial_y W dy.
	\end{align*}
    We present the estimation of $I$, $II$, $III$ in what follows. 

    \noindent\underline{The term $I$:} We first observe that  
    \[
    \begin{split}
    I &= - (\mu - \frac12) (\left\lVert\partial_yZ\right\rVert_{L^2}^2+ b \left\lVert\partial_yW\right\rVert_{L^2}^2 ) - \int_{0}^\infty \frac{3(\gamma+1)}{8}\partial_y \mathring z \mid \partial_y Z\mid^2 +  \frac{(3-\gamma)}{8}\partial_y\mathring z  \mid \partial_y W \mid^2 \ dy 
    \end{split}
    \] 
    It is sufficient to estimate the last integral and we will focus on the first term as the second one follows analogously. By recalling \eqref{profile be} from Proposition \ref{prop: mathring z},  
    	$$ |\partial_y\mathring z|\leq \begin{cases}
		A,\ \text{for } y\in[0,1],\\
		Ay^{-\mu},\ \text{for } y \ge 1,
	\end{cases}$$
	for some constant $A:=A(\gamma,\mu)$,   
   we split the integral into two: 
   \[
  \int_{0}^\infty |\partial_y \mathring z |   \mid \partial_y Z\mid^2  dy  \le A\int_{0}^{e^{\alpha\tau}}  \mid \partial_y Z\mid^2  dy  +A \int_{e^{\alpha\tau}}^{\infty}
 y^{-\mu} \mid \partial_y Z\mid^2   dy =: A (I_1+  I_2)
    \]
   where $\alpha>0$ is small to be determined. For $I_1$, by Hardy inequality (cf. Lemma \ref{hardy 1}),  
    \[
I_1 = \int_{0}^{e^{\alpha\tau}}y^{2({\bf{n}_{\mu}}-1)}\mid \frac{\partial_y Z}{y^{{\bf{n}_{\mu}}-1}}\mid^2 \ dy  
		\lesssim e^{2({\bf{n}_{\mu}}-1)\alpha\tau} \left\lVertZ\right\rVert_{\dot H^{\bf{n}_{\mu}}}^2
    \]
 For $I_2$, we bound by 
 \[
 I_2 \le e^{-\mu \alpha \tau} \left\lVert\partial_y Z\right\rVert_{L^2} ^2 
 \]
	Hence, by the bootstrap assumption of Proposition \ref{bootstrap lemma}, we arrive 
	\begin{equation}\begin{aligned}\label{I-1}
     \int_{0}^\infty\frac{3(\gamma+1)}{8}  |\partial_y \mathring z|   \mid \partial_y Z\mid^2  dy   \le C e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau}  + C B^2 e^{-(\mu\alpha+(2\mu-1)\mathtt{a_2})\tau} 
	\end{aligned}\end{equation} and  
   similarly, 
	\begin{equation}\begin{aligned}\label{I-2}
      \int_{0}^\infty\frac{(3-\gamma)}{8}  | \partial_y \mathring z  | \mid \partial_y W\mid^2  dy  \le C e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau}  + C B^2 e^{-(\mu\alpha+(2\mu-1)\mathtt{a_2})\tau}
	\end{aligned}\end{equation}
     for some constant $C>0$. 
	Therefore, combining \eqref{I-1} and \eqref{I-2}, we have 
	\begin{equation}\begin{aligned}\label{I}
		I \leq -(\mu-\frac{1}{2} ) \Big(\left\lVert\partial_y Z\right\rVert_{L^2}^2 +\left\lVert\partial_y W\right\rVert_{L^2} ^2\Big) + C e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau} + CB^2 e^{-(\mu\alpha+(2\mu-1)\mathtt{a_2})\tau}.
	\end{aligned}\end{equation}

   \noindent \underline{The term $II$:} We estimate $II$ term by term: 
	\begin{align*}
		II 
		&=-\frac{3-\gamma}{4} \int_{0}^\infty  \partial_y \mathring z\partial_y W \partial_y Z dy - \frac{3-\gamma}{4}\int_{0}^\infty \partial_y^2 \mathring zW \partial_y Z dy- \frac{\gamma+1}{4} \int_{0}^\infty \partial_y^2 \mathring z Z\partial_y Z dy.
	\end{align*}
    The estimation of the first term is similar to the previous case $I$:   
	\begin{equation}\begin{aligned}\label{II-2}
		\left| \int_{0}^\infty  \partial_y \mathring z\partial_y W \partial_y Z dy \right|  &\leq \frac12  \int_{0}^\infty | \partial_y \mathring z | \mid\partial_y W \mid^2 dy  +\frac12   \int_{0}^\infty | \partial_y \mathring z | \mid\partial_y Z \mid^2 dy \\
		&\leq C e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau} + CB^2 e^{-(\mu\alpha+(2\mu-1)\mathtt{a_2})\tau}.
	\end{aligned}\end{equation}
	For the second term, we apply Holder inequality and obtain
	\begin{align*}
		\left| \int_{0}^\infty \partial_y^2 \mathring zW \partial_y Z dy \right| \leq \Big(\int_{0}^\infty \mid\partial_y^2 \mathring z  W\mid^2  dy\Big)^{\frac12} \Big(\int_{0}^\infty\mid\partial_y Z \mid^2 dy\Big)^{\frac12}
	\end{align*}
	As in the previous case,  
    due to the different behaviors of $\partial_y^2\mathring z$ for $y\ll 1$ and $1\ll y$
	 from Proposition \ref{prop: mathring z}: 
	$$ |\partial_y^2\mathring z|\leq \begin{cases}
		Ay^{\beta-2},\ \text{for } y \in [0,1],\\
		Ay^{-\mu-1},\ \text{for }  y \ge  1,
	\end{cases}$$
	we  separate the domain of integration 
	\begin{align*} 
       &\int_{0}^\infty \mid\partial_y^2 \mathring zW\mid^2 dy = \int_0^{1}\mid\partial_y^2 \mathring zW\mid^2 dy + \int_{1}^{e^{\alpha\tau}} \mid\partial_y^2 \mathring zW\mid^2 dy +\int_{e^{\alpha\tau}}^\infty\mid\partial_y^2 \mathring zW\mid^2 dy \\
        &\leq A\int_0^{1} y^{2\beta-4} \mid W\mid^2 dy +  A\int_{1}^{e^{\alpha\tau}} y^{-2\mu-2}\midW\mid^2 dy + A\int_{e^{\alpha\tau}}^\infty y^{-2\mu-2}\midW\mid^2 dy\\
        &\leq A (1+ e^{2({\bf{n}_{\mu}}-1-\mu)\alpha\tau}) \int_0^{e^{\alpha\tau}}\mid\frac{W}{y^{\bf{n}_{\mu}}}\mid^2 dy + Ae^{-2\mu\alpha\tau}\int_{e^{\alpha\tau}}^\infty \mid  \frac{W}{y}\mid^2 \ dy
	\end{align*}
   By using 
   the bootstrap assumptions of Proposition  \ref{bootstrap lemma}, 
	\begin{equation}\label{II-1}
		\left| \int_{0}^\infty \partial_y^2 \mathring zW \partial_y Z dy \right| \leq \Big( C  e^{(({\bf{n}_{\mu}}-1-\mu)\alpha -\mathtt{a_1} )\tau }+C B e^{-\mu\alpha\tau}e^{-(\mu-\frac12)\mathtt{a_2}\tau} \Big) B e^{-(\mu-\frac12)\mathtt{a_2}\tau}.
	\end{equation}
	The third term can be estimated in the same way as in the second term by noting that
    \[
		\left| \int_{0}^\infty \partial_y^2 \mathring zZ \partial_y Z dy \right| \leq \Big(\int_{0}^\infty \mid\partial_y^2 \mathring z  Z \mid^2  dy\Big)^{\frac12} \Big(\int_{0}^\infty\mid\partial_y Z \mid^2 dy\Big)^{\frac12}
    \]
    We deduce that 
    \begin{equation}\label{II-3}
		\left| \int_{0}^\infty \partial_y^2 \mathring zZ \partial_y Z dy \right| \leq \Big( C  e^{(({\bf{n}_{\mu}}-1-\mu)\alpha -\mathtt{a_1} )\tau }+C B e^{-\mu\alpha\tau}e^{-(\mu-\frac12)\mathtt{a_2}\tau} \Big) B e^{-(\mu-\frac12)\mathtt{a_2}\tau}.
	\end{equation}
 Combining  \eqref{II-2}, \eqref{II-1}, and \eqref{II-3}, 
         we conclude 
		 \begin{equation}\begin{aligned}\label{II}
		 	II \leq & \  C e^{( 2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau} 
            + C B^2 e^{-(\mu\alpha + (2\mu-1)\mathtt{a_2})\tau}   
		 \end{aligned}\end{equation}
	for some constant $C>0$. Here we have used the Cauchy-Schwartz inequality to bound the linear-in-$B$ term in \eqref{II-1}, and \eqref{II-3} by the right-hand-side of \eqref{II}. 

		\noindent \underline{The term $III$}: The first term of $III$ can be bounded by using H\"{o}lder inequality, Lemma \ref{estimate of Schi} and the bootstrap assumptions of Proposition \ref{bootstrap lemma}:
		 \begin{equation}\begin{aligned}\label{II-4}
		 	\Big| \int_{0}^\infty \partial_y\mathcal S_z \partial_y Z dy\Big| & \leq \left\lVert\partial_y\mathcal S_z\right\rVert_{L^2} \left\lVert\partial_y Z\right\rVert_{L^2}
			\leq CB y_0^{\frac{-4\mu +1}{2}}                   
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{-(\mu-\frac12)\mathtt{a_2}\tau}.
		 \end{aligned}\end{equation}
The estimation of remaining two integrals in $III$ is the same. Therefore, we only present the estimation of the first remaining integral involving $\partial_y\mathcal N_z$ and $\partial_y\mathcal T_z$. We first split $\partial_y\mathcal N_z$ into two parts: 
		 \begin{align*}
         \partial_y\mathcal N_z &  = \partial_y\Big( (\frac{\gamma+1}{4}M_z+\frac{3-\gamma}{4}M_w+\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4}W)\partial_yZ\Big)  +\partial_y\Big( (\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4} W)\partial_yM_z\Big)\\
        &  = \mathcal N_z^{1,1} + \mathcal N_z^{1,2}
         \end{align*}
    For $\int \mathcal N_z^{1,1} \partial_y Z dy $,  by integration by parts, we obtain 
		 \begin{align*}
		 	- \int_0^\infty \mathcal N_z^{1,1} \partial_y Z dy 
			&= - \frac12 \int_0^\infty  \partial_y(\frac{\gamma+1}{4}M_z+\frac{3-\gamma}{4}M_w+\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4}W)\mid\partial_yZ \mid^2 dy \\
			&\leq A ( \left\lVert\partial_y M_z\right\rVert_{L^\infty} +\left\lVert\partial_y M_w\right\rVert_{L^\infty}) \int_0^{1}|\partial_y Z|^2 dy   + A  (  \left\lVert\partial_y Z\right\rVert_{L^\infty} +\left\lVert\partial_y W\right\rVert_{L^\infty} ) \left\lVert\partial_y Z\right\rVert_{L^2}^2.
		 \end{align*}
		 We observe that $\int_0^1|\partial_y Z|^2 dy \lesssim \int_0^1|\frac{\partial_y Z}{y^{{\bf{n}_{\mu}}-1}}|^2 dy \lesssim \left\lVertZ\right\rVert_{\dot H^{\bf{n}_{\mu}}}^2 $ by Hardy inequality. By using Proposition \ref{prop payi mz mw}, Lemma  \ref{Linfty decay} 
         and  the assumptions of Proposition \ref{bootstrap lemma}, we further bound 
		 $$
		 	- \int_0^\infty \mathcal N_z^{1,1} \partial_y Z dy \leq C e^{-\mathtt{a_0} \tau} e^{-2\mathtt{a_1} \tau} 
            + C B^{3- \frac{1}{2({\bf{n}_{\mu}}-1)}} e^{\frac{-\mathtt{a_1}}{2({\bf{n}_{\mu}}-1)}\tau} e^{-\left(3-\frac{1}{2({\bf{n}_{\mu}}-1)}\right)(\mu-\frac12)\mathtt{a_2} \tau}.
		 $$
		 Next, since $\text{supp}(M_z), \text{supp}(M_w) \in [0,1]$, 
         by using Young's inequality, we bound
		 \begin{align*}
         	& - \int_0^\infty \mathcal N_z^{1,2} \partial_y Z dy\\
            &= - \int_0^\infty  (\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4} W)\partial_y^2M_z  \partial_y Z dy - \int_0^\infty (\frac{\gamma+1}{4}\partial_y Z+\frac{3-\gamma}{4} \partial_y W)\partial_yM_z \partial_y Z dy \\ 
			&\leq (\left\lVert\partial_y^2M_z\right\rVert_{L^\infty}+\left\lVert\partial_yM_z\right\rVert_{L^\infty})\Big( \int_0^{1} \mid Z\mid^2+ \mid W\mid^2 dy + \int_0^{1}  \mid \partial_yW\mid^2 +  \mid \partial_yZ\mid^2 dy)\\
			&\leq (\left\lVert\partial_y^2M_z\right\rVert_{L^\infty}+\left\lVert\partial_yM_z\right\rVert_{L^\infty})                       
            \Big( \int_0^{1}  \mid \frac{Z}{y^{\bf{n}_{\mu}}}\mid^2+ \mid \frac{W}{y^{\bf{n}_{\mu}}}\mid^2  dy + \int_0^{1}  \mid \frac{\partial_yW}{y^{{\bf{n}_{\mu}}-1}}\mid^2 dy+\int_0^{1}  \mid \frac{\partial_yZ}{y^{{\bf{n}_{\mu}}-1}}\mid^2 dy)\\
			&\leq (\left\lVert\partial_y^2M_z\right\rVert_{L^\infty}+\left\lVert\partial_yM_z\right\rVert_{L^\infty})                                
            \Big( \left\lVertW\right\rVert_{\dot H^{\bf{n}_{\mu}}}^2+\left\lVertZ\right\rVert_{\dot H^{\bf{n}_{\mu}}}^2\Big)
		 \end{align*}
		 where we have used                    
         Lemma \ref{hardy 1} in the last step. Hence,
		 $$
		 	- \int_0^\infty \mathcal N_z^{1,2} \partial_y Z dy                                                           
            \leq C e^{-\mathtt{a_0} \tau}e^{-2\mathtt{a_1} \tau}.
		 $$
		 For the last piece, recalling the expression \eqref{nz nmz} of $\partial_y\mathcal T_z$ 
		 \begin{align*}
		 	- \int_0^\infty   \partial_y\mathcal T_z \partial_y Z  dy &= - \int_0^1\partial_y\Big(\partial_\tau M_z+  \mathcal L_z M_z+\frac{3-\gamma}{4}\partial_y \mathring z M_w +(\frac{\gamma+1}{4}M_z+\frac{3-\gamma}{4}M_w)\partial_yM_z\Big) \partial_y Z  dy \\
			&\leq C e^{-\mathtt{a_0} \tau} (\int_0^{1} |\frac{\partial_y Z}{y^{{\bf{n}_{\mu}}-1}}|^2 dy)^\frac12 \le  C e^{-\mathtt{a_0} \tau} \left\lVertZ\right\rVert_{\dot H^{\bf{n}_{\mu}}}  
			\leq  C e^{-(\mathtt{a_0}+ \mathtt{a_1} )\tau}  
		 \end{align*}
	where we used Proposition \ref{prop payi mz mw} in the first inequality and Hardy inequality (cf. Lemma \ref{hardy 1}) 
    in the second inequality. Hence,  
	\begin{equation}\begin{aligned}\label{III}
	 III&\leq CB y_0^{\frac{-4\mu +1}{2}} 
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{-(\mu-\frac12)\mathtt{a_2}\tau}+ C e^{-(\mathtt{a_0}+\mathtt{a_1}) \tau}\\                          
            &\quad + C B^{3-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{\frac{-\mathtt{a_1}}{2({\bf{n}_{\mu}}-1)}\tau} e^{-\left(3-\frac{1}{2({\bf{n}_{\mu}}-1)}\right)(\mu-\frac12)\mathtt{a_2} \tau}.
	\end{aligned}\end{equation}

         Putting the estimates together from \eqref{I}, \eqref{II} and \eqref{III}, and choosing $\alpha = \frac{\mathtt{a_1}}{2({\bf{n}_{\mu}}-1)}$ and  with $\mathtt{a_1}<\mathtt{a_0}$, we arrive at 
		 \begin{equation}\begin{aligned}\notag 
\frac12&\partial_\tau \Big(\left\lVert\partial_yZ\right\rVert_{L^2}^2+\left\lVert\partial_yW\right\rVert_{L^2}^2\Big)\\ 
			\leq & -(\mu-\frac{1}{2} ) \Big(\left\lVert\partial_y Z\right\rVert_{L^2}^2 +\left\lVert\partial_y W\right\rVert_{L^2} ^2\Big)  + C e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau} + CB^2 e^{-\mu\alpha \tau }e^{-(2\mu-1)\mathtt{a_2} \tau} \\ 
			&
           +CB y_0^{\frac{-4\mu +1}{2}} 
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{-(\mu-\frac12)\mathtt{a_2}\tau} + C e^{-(\mathtt{a_0}+\mathtt{a_1} )\tau}                         
            + C B^{3-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{\frac{-\mathtt{a_1}}{2({\bf{n}_{\mu}}-1)}\tau} e^{-\left(3-\frac{1}{2({\bf{n}_{\mu}}-1)}\right)(\mu-\frac12)\mathtt{a_2} \tau}  \\ 
          \leq & -(\mu-\frac{1}{2} ) \Big(\left\lVert\partial_y Z\right\rVert_{L^2}^2 +\left\lVert\partial_y W\right\rVert_{L^2} ^2\Big)  + C   e^{-\mathtt{a_1} \tau} + CB^2 e^{-\mu\alpha \tau }e^{-(2\mu-1)\mathtt{a_2} \tau} \\
          &+CB y_0^{\frac{-4\mu +1}{2}} 
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{-(\mu-\frac12)\mathtt{a_2}\tau}
		 \end{aligned}\end{equation}
        At the second inequality we used   $e^{-(\mathtt{a_0}+\mathtt{a_1} )\tau} \le e^{(2({\bf{n}_{\mu}}-1)\alpha-2\mathtt{a_1}) \tau}  =  e^{-\mathtt{a_1} \tau}$ and   $e^{\frac{-\mathtt{a_1}}{2(n-1)}\tau} e^{-\left(3-\frac{1}{2(n-1)}\right)(\mu-\frac12)\mathtt{a_2} \tau}  \le e^{-\mu\alpha \tau }e^{-(2\mu-1)\mathtt{a_2} \tau} $.

\label{lemma L2}
    Let $\gamma\in(1,3)$ and $\mu\in[\frac{1}{2},1)$.  Under the assumptions of Proposition \ref{bootstrap lemma}, we have
    \begin{align}
        \partial_\tau\Big(\left\lVertZ\right\rVert_{L^2}^2+\left\lVertW\right\rVert_{L^2}^2\Big)\leq &(3-2\mu) (\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2) +CB^2 e^{-\frac{\mu\mathtt{a_1}}{2{\bf{n}_{\mu}}-\mu}\tau} e^{(3-2\mu)\tau}+CBe^{(\frac{3}{2}-\mu)\tau}(G[\mu])^{\frac12}\notag \\
            &+B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau}e^{-\frac{1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1}\tau}B^2 e^{(3-2\mu)\tau} \label{l2 main}
    \end{align}
    where $G[\mu]$ is defined in \eqref{Fmu}.

By following a similar computation step 
     as in Lemma \ref{weighted L^2 estimates}, we obtain
     \[
     \begin{split}
\frac12\partial_\tau(\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2) \leq & (\frac32-\mu) (\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2)+ \int_0^\infty    |\partial_y \mathring z| |Z|^2+|\partial_y \mathring z | |W|^2 +| \partial_y\mathring z| WZ\ dy \\
&+\left| \langle F_1,Z \rangle\right|+\left| \langle F_2,W \rangle\right|.
    \end{split}
     \]
     We first estimate the quadratic term on the first line. By recalling Proposition \ref{prop: mathring z}
     $$ |\partial_y\mathring z|\leq \begin{cases}
		A,\ \text{for } y\in[0,1],\\
		Ay^{-\mu},\ \text{for } y \ge 1,
	\end{cases}$$
    We split the integral domains into three pieces:
    \begin{equation}\begin{aligned}\label{L2 linear}
        \int_0^\infty |\partial_y\mathring z| Z^2 \ dy &= \int_0^1 |\partial_y\mathring z| Z^2 \ dy+ \int_1^{e^{\alpha\tau}}|\partial_y\mathring z |Z^2 \ dy +\int_{e^{\alpha\tau}}^\infty |\partial_y\mathring z |Z^2 \ dy \\
        &\lesssim \int_0^1  Z^2 \ dy+ \int_1^{e^{\alpha\tau}} y^{-\mu}Z^2 \ dy +\int_{e^{\alpha\tau}}^\infty  y^{-\mu} Z^2 \ dy \\
        &\lesssim (1+e^{(2{\bf{n}_{\mu}}-\mu)\alpha\tau})\int_0^{e^{\alpha\tau}}  \left|\frac{Z}{y^{\bf{n}_{\mu}}}\right|^2 \ dy + e^{-\mu\alpha\tau} \left\lVertZ\right\rVert_{L^2}^2 \\
        &\lesssim e^{(2{\bf{n}_{\mu}}-\mu)\alpha\tau-2\mathtt{a_1} \tau}+B^2 e^{-\mu\alpha\tau} e^{(3-2\mu)\tau}.
    \end{aligned}\end{equation}
    where $\alpha$ will be determined later and we have used the assumptions of Proposition \ref{bootstrap lemma} in the last inequality.
        The remaining two terms are estimated in a similar manner, with the cross terms treated first by applying Young’s inequality. We now proceed to estimate the terms regarding $F_1$ and $F_2$. Since the estimate for $F_2$ follows in an analogous manner to that of $F_1$, we only present the detailed estimate for $F_1$. Recall the expression 
           $ F_1 = \mathcal S_z -\mathcal N_z - \mathcal T_z$ 
        where $\mathcal S_z$, $\mathcal N_z$ and $\mathcal T_z$ are defined in \eqref{nz nmz}. We estimate term by term.

        \noindent\underline{The source term $\mathcal S_z$}: By using Holder inequality,  
        \begin{align*}
          \Big|  \int_0^\infty \bar z (1-\chi) \partial_y \mathring z Z \ dy \Big| \lesssim \int_{y_0e^{(1-\mu)(\tau-\tau_0)}}^{2y_0e^{\tau-\tau_0}}y^{1-2\mu} |Z| \ dy &\lesssim \left\lVertZ\right\rVert_{L^2} \big(\int_{y_0e^{(1-\mu)(\tau-\tau_0)}}^{2y_0e^{\tau-\tau_0}} y^{2-4\mu} \ dy\big)^{\frac12}.
        \end{align*}
        Now, depending on $\mu$, the integral of $y^{2-4\mu}$ is solved differently. 
        \begin{equation}\begin{aligned}\label{Fmu}
            \int_{y_0e^{(1-\mu)(\tau-\tau_0)}}^{2y_0e^{\tau-\tau_0}} y^{2-4\mu} \ dy \leq \begin{cases}
                Cy_0^{3-4\mu} e^{(3-4\mu)(\tau-\tau_0)}, \ \text{ when }\mu\in[\frac12,\frac34),\\
                \ln(2y_0e^{\tau-\tau_0}),  \ \text{ when }\mu=\frac34,\\
                Cy_0^{3-4\mu}e^{(3-4\mu)(1-\mu)(\tau-\tau_0)}, \ \text{ when }\mu\in(\frac34,1).
            \end{cases}
        \end{aligned}\end{equation}
        For notational convenience, we denote the right-hand side of \eqref{Fmu} by $G[\mu]$. Hence, by using the assumptions of Proposition \ref{bootstrap lemma}, we demonstrate
        \begin{equation}\label{L2 Sz}
            \Big| \int_0^\infty \bar z (1-\chi) \partial_y \mathring z Z \ dy \Big| \leq CBe^{(\frac{3}{2}-\mu)\tau} (G[\mu])^{\frac12}.
        \end{equation}

       \noindent \underline{The nonlinear term $\mathcal N_z$}:
        We first do the integration by parts, 
        \begin{align*}
           & \int_0^\infty  (\frac{\gamma+1}{4}M_z+\frac{3-\gamma}{4}M_w+\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4}W)\partial_yZ Z+(\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4} W)\partial_yM_z Z \ dy \\
          =&-\frac12\int_0^\infty  (\frac{\gamma+1}{4}\partial_yM_z+\frac{3-\gamma}{4}\partial_yM_w+\frac{\gamma+1}{4}\partial_yZ+\frac{3-\gamma}{4}\partial_yW)\left| Z\right|^2+(\frac{\gamma+1}{4}Z+\frac{3-\gamma}{4} W)\partial_yM_z Z \ dy \\
          \lesssim & \Big(\left\lVert\partial_yM_z\right\rVert_{L^\infty}+\left\lVert\partial_yM_w\right\rVert_{L^\infty}+\left\lVert\partial_yZ\right\rVert_{L^\infty}+\left\lVert\partial_yW\right\rVert_{L^\infty}\Big)(\left\lVertZ\right\rVert_{L^2}^2 +\left\lVertW\right\rVert_{L^2}^2 )
        \end{align*}
        where we have used H\"{o}lder inequality in the last step. Next, we apply the assumptions of Proposition \ref{bootstrap lemma}, Lemma \ref{prop payi mz mw} , and Lemma \ref{Linfty decay} to obtain
        \begin{equation}\label{L2 Nz}
            \Big| \int_0^\infty \mathcal N_z Z \ dy \Big| \lesssim (e^{-\mathtt{a_0} \tau}+B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau}e^{\frac{-1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1}\tau})B^2 e^{(3-2\mu)\tau}.
        \end{equation}

        \noindent\underline{The nonlinear term $\mathcal T_z$}:
        By using H\"{o}lder inequality:
        \begin{equation}\label{l2 Tz}
          \Big|  \int_0^\infty \mathcal T_z Z \ dy\Big|  \lesssim \left\lVert\mathcal T_z\right\rVert_{L^2} \left\lVertZ\right\rVert_{L^2} \lesssim B e^{-\mathtt{a_0} \tau}e^{(\frac{3}{2}-\mu)\tau} 
        \end{equation}
        where Lemma \ref{prop Tz Tw /y} and the assumptions of Proposition \ref{bootstrap lemma} have been used. Combing \eqref{L2 linear}, \eqref{L2 Sz}, \eqref{L2 Nz}, \eqref{l2 Tz}, and choosing $\alpha=\frac{\mathtt{a_1}}{2{\bf{n}_{\mu}}-\mu}$, we derive
        \begin{align*}
            \frac12\partial_\tau(\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2) \leq & (\frac32-\mu) (\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2) +Ce^{-\mathtt{a_1} \tau}+CB^2 e^{-\frac{\mu\mathtt{a_1}}{2{\bf{n}_{\mu}}-\mu}\tau} e^{(3-2\mu)\tau}\\
            &+CBe^{(\frac{3}{2}-\mu)\tau} (G[\mu])^{\frac12}+B e^{-\mathtt{a_0} \tau}e^{(\frac{3}{2}-\mu)\tau}\\
            &+C(e^{-\mathtt{a_0} \tau}+B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau}e^{-\frac{1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1}\tau})B^2 e^{(3-2\mu)\tau}\\
            \leq & (\frac32-\mu) (\left\lVertZ\right\rVert_{L^2}^2 +  \left\lVertW\right\rVert_{L^2}^2) +CB^2 e^{-\frac{\mu\mathtt{a_1}}{2{\bf{n}_{\mu}}-\mu}\tau} e^{(3-2\mu)\tau}+CBe^{(\frac{3}{2}-\mu)\tau}(G[\mu])^{\frac12} \\
            &+B^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}} e^{-(1-\frac{1}{2({\bf{n}_{\mu}}-1)})(\mu-\frac12)\mathtt{a_2} \tau}e^{-\frac{1}{2({\bf{n}_{\mu}}-1)}\mathtt{a_1}\tau}B^2 e^{(3-2\mu)\tau}
        \end{align*}
        where $C$ is a constant. At the last inequality, we have used $e^{-\mathtt{a_0}\tau}<e^{-\mathtt{a_1}\tau}\leq e^{-\frac{\mu\mathtt{a_1}}{2{\bf{n}_{\mu}}-\mu}\tau}$.

From Lemma \ref{lemma nonlinear H^1}, we have
    \begin{align*}
    \partial_\tau\Big(e^{(2\mu-1)\tau}(\left\lVert\partial_yZ\right\rVert_{L^2}^2+\left\lVert\partial_yW\right\rVert_{L^2}^2)\Big)\leq &   C   e^{(2\mu-1-\mathtt{a_1}) \tau} + CB^2 e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} \tau }e^{(2\mu-1)(1-\mathtt{a_2}) \tau} \\
          &+CB y_0^{\frac{-4\mu +1}{2}} 
            e^{\frac{(-4\mu+1)(1-\mu)}{2}(\tau-\tau_0)}e^{(\mu-\frac12)(2-\mathtt{a_2})\tau}.
    \end{align*}
    Integrating the above ODE inequality over $[\tau_0, \tau]$, we derive
    \begin{align*}
        &\left\lVert(\partial_yZ(\tau,\cdot), \partial_y W(\tau,\cdot))\right\rVert_{L^2}^2 \\
        &\leq e^{-(2\mu-1)(\tau-\tau_0)} \left\lVert(\partial_yZ(\tau_0,\cdot), \partial_y W(\tau_0,\cdot))\right\rVert_{L^2}^2 
         + C  e^{-(2\mu-1)\tau}\int_{\tau_0}^{\tau} e^{(2\mu-1-\mathtt{a_1}) \tau'} \ d\tau'\\
        &\quad + CB^2 e^{-(2\mu-1)\tau}\int_{\tau_0}^{\tau} e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} \tau' }e^{(2\mu-1)(1-\mathtt{a_2}) \tau'} d\tau'\\
        &\quad + CB y_0^{\frac{-4\mu +1}{2}}e^{\frac{-(-4\mu+1)(1-\mu)}{2}\tau_0} e^{-(2\mu-1)\tau}\int_{\tau_0}^{\tau}
            e^{\frac{(-4\mu+1)(1-\mu)}{2}\tau'}e^{(\mu-\frac12)(2-\mathtt{a_2})\tau'}d\tau'\\
        &=: I^1+II^1+III^1+IV^1.
    \end{align*}
We analyze the terms sequentially, following the order of choosing $\tau_0$, $\sigma_0$, and $y_0$. We first analyze $III^1$. We observe that the sign of $-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(2\mu-1)(1-\mathtt{a_2})$ is indeterminate. To verify it, we recall the definition \eqref{def ndmu} of ${\bf{n}_{\mu}}$. In particular, we note that $0<\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} \to 0$ as $\mu\to 1$, while $\mathtt{a_2}$ is small. Consequently, the sign of the above expression may vary with the value of $\mu$, and it is thus natural to distinguish the following two cases: when $-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(2\mu-1)(1-\mathtt{a_2})\neq 0$,
\begin{align*}
    III^1 &= 
        B^2e^{-(2\mu-1)\mathtt{a_2} \tau}\frac{ C e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)}\tau_0 }}{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(2\mu-1)(1-\mathtt{a_2})}\Big(  e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)}(\tau-\tau_0) }-e^{-(2\mu-1)(1-\mathtt{a_2})(\tau- \tau_0)}\Big)\\
        &\leq  B^2e^{-(2\mu-1)\mathtt{a_2} \tau}\frac{ C e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)}\tau_0 }}{\left|-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(2\mu-1)(1-\mathtt{a_2})\right|},\ \text{ for any }\tau\in[\tau_0,\tau_1],
\end{align*}
where we have used $\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)}>0$ and $(2\mu-1)(1-\mathtt{a_2})\geq 0$ in the last step. And, when $-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(\mu-\frac12)(2-\mathtt{a_2})= 0$, we have $(2\mu-1)(1-\mathtt{a_2})>0$ and
$$
    III^1 =e^{-(2\mu-1)\mathtt{a_2} \tau} CB^2 e^{-(2\mu-1)(1-\mathtt{a_2})\tau}(\tau-\tau_0)\leq  B^2e^{-(2\mu-1)\mathtt{a_2}\tau} \frac{C e^{-(2\mu-1)(1-\mathtt{a_2})\tau_0}}{e(2\mu-1)(1-\mathtt{a_2})}
$$
where we have used the fact that $e^{-ax}x\leq \frac{1}{ae}$ with $a>0$ for any $x\geq 0$.
We then choose $\tau_0$ sufficiently large such that 
        \begin{equation}\begin{aligned}\label{B}
       \frac{ C e^{-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)}\tau_0 }}{\left|-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(2\mu-1)(1-\mathtt{a_2})\right|} \leq \frac{1}{4}, \ \text{when }\left|-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(\mu-\frac12)(2-\mathtt{a_2})\right| \neq 0,\\
       \frac{C e^{-(2\mu-1)(1-\mathtt{a_2})\tau_0}}{e(2\mu-1)(1-\mathtt{a_2})} \leq \frac{1}{4}, \ \text{when }\left|-\frac{\mathtt{a_1} \mu}{2({\bf{n}_{\mu}}-1)} +(\mu-\frac12)(2-\mathtt{a_2})\right| = 0,
    \end{aligned}\end{equation}
   to obtain
    \begin{equation}\label{H1 III}
        III^1 \leq \frac{1}{4}B^2e^{-(2\mu-1)\mathtt{a_2} \tau}.
    \end{equation}
    We next analyze $II^1$. Similarly, $2\mu-1\in[0,1]$ and $\mathtt{a_1}$ is small. The sign of $2\mu-1-\mathtt{a_1}$ is indeterminate as well. Hence, we split it into two cases: when $2\mu-1-\mathtt{a_1} \neq 0$,
    \begin{align*}
       II^1&= e^{-(2\mu-1)\mathtt{a_2}\tau}\frac{C}{2\mu-1-\mathtt{a_1}}\Big( e^{-(\mathtt{a_1}-(2\mu-1)\mathtt{a_2}) \tau}- e^{-(2\mu-1)(1-\mathtt{a_2})\tau}e^{(2\mu-1-\mathtt{a_1})\tau_0}\Big)\\
       &\leq e^{-(2\mu-1)\mathtt{a_2}\tau}\frac{C}{\left|2\mu-1-\mathtt{a_1}\right|}\Big( e^{-(\mathtt{a_1}-(2\mu-1)\mathtt{a_2}) \tau}+ e^{-(2\mu-1)(1-\mathtt{a_2})\tau}e^{-\left| 2\mu-1-\mathtt{a_1}\right|\tau_0}\Big).
    \end{align*}
When $2\mu-1-\mathtt{a_1}=0$, then $(2\mu-1)(1-\mathtt{a_2})\neq 0$ due to \eqref{sequence a_1, a_2, a_0}, and
$$
    II^1= e^{-(2\mu-1)\mathtt{a_2}\tau} C e^{-(2\mu-1)(1-\mathtt{a_2})\tau} (\tau-\tau_0) \leq e^{-(2\mu-1)\mathtt{a_2}\tau}\frac{Ce^{-1-(2\mu-1)(1-\mathtt{a_2})\tau_0}}{(2\mu-1)(1-\mathtt{a_2})}
$$
where we also used $e^{-ax}x\leq \frac{1}{ae}$ with $a>0$ for any $x\geq 0$ in the last inequality. Now, by choosing $\tau_0$ sufficient large such that
    \begin{equation}\begin{aligned}\label{tau0}
        \frac{C}{\left|2\mu-1-\mathtt{a_1}\right|}\Big( e^{-(\mathtt{a_1}-(2\mu-1)\mathtt{a_2}) \tau}+ e^{-(2\mu-1)(1-\mathtt{a_2})\tau}e^{-\left| 2\mu-1-\mathtt{a_1}\right|\tau_0}\Big)\leq\frac{1}{4}B^2,\ \text{when }2\mu-1-\mathtt{a_1}\neq 0,\\
        \frac{Ce^{-1-(2\mu-1)(1-\mathtt{a_2})\tau_0}}{(2\mu-1)(1-\mathtt{a_2})}\leq \frac{1}{4}B^2,\ \text{when }2\mu-1-\mathtt{a_1}= 0,
    \end{aligned}\end{equation}
we have 
\begin{equation}\label{H1 II}
    II^1\leq \frac{1}{4}B^2e^{-(2\mu-1)\mathtt{a_2} \tau}.
\end{equation}
For $I^1$, by the initial condition $\left\lVert(Z(\tau_0,\cdot), W(\tau_0,\cdot))\right\rVert_{H^{\bf{n}_{\mu}}}\leq \sigma_0$, we have 
    \begin{align}\label{H1 I}
        I^1&\le e^{-(2\mu-1)\mathtt{a_2}\tau}  e^{-(2\mu-1)(1-\mathtt{a_2})\tau}e^{(2\mu-1)\tau_0}\sigma_0^2\leq \frac{1}{4}B^2e^{-(2\mu-1)\mathtt{a_2} \tau}
    \end{align}
    if we choose $\sigma_0$ be sufficiently small such that
    \begin{equation} \label{delta1}
        e^{-(2\mu-1)(1-\mathtt{a_2})\tau_0}e^{(2\mu-1)\tau_0}\sigma_0^2\leq \frac{1}{4}B^2.
    \end{equation}
    For the last piece $IV^1$, we split it into two cases: when $\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)(2-\mathtt{a_2})\neq 0$,
    \begin{align*}
        IV^1 &= e^{-(2\mu-1)\mathtt{a_2}\tau} \frac{ CB y_0^{\frac{-4\mu +1}{2}}}{\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)(2-\mathtt{a_2})}\Big(e^{-\frac{(-4\mu+1)(1-\mu)}{2}\tau_0}e^{\big(\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)\mathtt{a_2}\big)\tau} \\
        &-e^{(\mu-\frac12)\mathtt{a_2}\tau_0}e^{-(\mu-\frac12)(2-2\mathtt{a_2})(\tau-\tau_0)}\Big)\\
        &\leq e^{-(2\mu-1)\mathtt{a_2}\tau} \frac{2 e^{(\mu-\frac12)\mathtt{a_2}\tau_0}CB y_0^{\frac{-4\mu +1}{2}}}{\left|\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)(2-\mathtt{a_2})\right|}.
     \end{align*}
    We have used $\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)\mathtt{a_2}<0$ and $(\mu-\frac12)(2-2\mathtt{a_2})>0$ from \eqref{sequence a_1, a_2, a_0} in the last inequality. When $\frac{(-4\mu+1)(1-\mu)}{2}+(\mu-\frac12)(2-\mathtt{a_2})= 0$, we then have $(2\mu-1)(1-\mathtt{a_2})>0$ and compute
     \begin{align*}
         IV^1 &= CB y_0^{\frac{-4\mu +1}{2}}e^{\frac{-(-4\mu+1)(1-\mu)}{2}\tau_0} e^{-(2\mu-1)\tau}(\tau-\tau_0)\\
        &=e^{-(2\mu-1)\mathtt{a_2}\tau} CB y_0^{\frac{-4\mu +1}{2}}e^{(\mu-\frac12)\mathtt{a_2}\tau_0}e^{-(2\mu-1)(1-\mathtt{a_2})(\tau-\tau_0)} (\tau-\tau_0)\\
        &\leq e^{-(2\mu-1)\mathtt{a_2}\tau}B \frac{Cy_0^{\frac{-4\mu +1}{2}}e^{(\mu-\frac12)\mathtt{a_2}\tau_0-1}}{(2\mu-1)(1-\mathtt{a_2})} 
     \end{align*}
    where we have replaced $\frac{(-4\mu+1)(1-\mu)}{2}$ by $-(\mu-\frac12)(2-\mathtt{a_2})$ in the third equality and used $e^{-ax}x\leq \frac{1}{ae}$ with $a>0$ for any $x\geq 0$ in the last inequality. Now, choosing 
    \begin{equation}
            y_0=e^{\vartheta \tau_0}, \ \text{where } \vartheta>0 \text{ to be determined}.
    \end{equation}
    Then
    \begin{equation}\label{y0}
    \frac{Cy_0^{\frac{-4\mu +1}{2}}e^{(\mu-\frac12)\mathtt{a_2}\tau_0-1}}{(2\mu-1)(1-\mathtt{a_2})} = \frac{C}{(2\mu-1)(1-\mathtt{a_2})} e^{\big(\frac{-4\mu +1}{2}\vartheta+(\mu-\frac12)\mathtt{a_2}\big)\tau_0-1}.
    \end{equation}
    Once we have
    \begin{equation}\label{vartheta}
        \frac{-4\mu +1}{2}\vartheta+(\mu-\frac12)\mathtt{a_2}<0
    \end{equation}
    together with $\tau_0$ sufficiently large,
    we establish
    \begin{equation}\label{H1 IV}
        IV^1\leq \frac{1}{4}B^2 e^{-(2\mu-1)\mathtt{a_2}\tau}.
    \end{equation}
    We conclude that, by selecting $\tau_0$, $\sigma_0$, $y_0$, and $\vartheta$ so as to satisfy \eqref{B}, \eqref{tau0}, \eqref{delta1}, \eqref{y0}, \eqref{vartheta} the estimates \eqref{H1 III}, \eqref{H1 II}, \eqref{H1 I} and \eqref{H1 IV} are derived, thereby establishing \eqref{pay z w}.

