From Lemma \ref{ode Hn}, 
	\begin{equation}\begin{aligned}
		 \partial_\tau (e^{\alpha^2\tau}F_{{\bf{n}_{\mu}}}(\tau))
	&\le   C { y_0^{\frac32-2\mu-{\bf{n}_{\mu}}}}e ^{-(1-\mu)({\bf{n}_{\mu}} +2\mu -\frac{3}{2}) (\tau-\tau_0)}  e^{\alpha^2\tau}e^{-\mathtt{a_1} \tau} +Ce^{\alpha^2\tau}e^{-\mathtt{a_0} \tau}e^{-\mathtt{a_1} \tau}\\
     &+ CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}e^{\alpha^2\tau}e^{-(\mu-\frac12)(1-\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_2}\tau} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau}
	\end{aligned}\end{equation}
    where
