        F_{{\bf{n}_{\mu}}}(\tau):=&\left\lVertZ(\tau,\cdot)\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2+b \left\lVertW(\tau,\cdot)\right\rVert_{\dot H^{{\bf{n}_{\mu}}}}^2 +  C(\left\lVert\frac{Z}{y^{{\bf{n}_{\mu}}}}(\tau,\cdot)\right\rVert_{L^2}^2 + b\left\lVert\frac{W}{y^{{\bf{n}_{\mu}}}}(\tau,\cdot)\right\rVert_{L^2}^2)\\
        \alpha^2:=&(1-\mu){\bf{n}_{\mu}} - \frac32 + \frac{\mu}{2} .
