        &+ Ce^{-\alpha^2\tau}\int_{\tau_0}^\tau e^{(\alpha^2-\mathtt{a_0}-\mathtt{a_1})\tau'} \ d\tau' + CB^{1-\frac{1}{2({\bf{n}_{\mu}}-1)}}e^{-\alpha^2\tau}\int_{\tau_0}^\tau e^{-(\mu-\frac12)(1-\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_2}\tau'} e^{-(2+\frac{1}{2({\bf{n}_{\mu}}-1)})\mathtt{a_1} \tau'} e^{\alpha^2 \tau'}\ d\tau'\\
