    V:=C\int_{\tau_0}^\tau e^{-(\frac32-\mu)\tau'}(G[\mu])^{\frac12}\ dy\leq \frac{1}{4}B.
 \end{equation}
 By recalling $G[\mu]$ as defined in \eqref{Fmu}, we bound it case by case. When $\mu\in[\frac12,\frac34)$, we compute
 \begin{align*}
   Cy_0^{\frac32-2\mu}\int_{\tau_0}^\tau e^{-(\frac32-\mu)\tau'} e^{(\frac32-2\mu)(\tau'-\tau_0)}\ dy &\leq \frac{y_0^{\frac32-2\mu}}{\mu}e^{-(\frac{3}{2}-\mu)\tau_0} = \frac1\mu e^{\Big((\frac{3}{2}-2\mu)\vartheta -\frac32+\mu\Big)\tau_0} = \frac{1}{\mu} e^{-\mu\tau_0} \leq \frac{1}{4}B
 \end{align*}
 for $\tau_0$ sufficiently large with 
$\vartheta=1$ such that 
 \begin{equation}\label{y_0}
 y_0=e^{\tau_0}.
 \end{equation}
 It is a routine matter to verify that \eqref{vartheta} and \eqref{vartheta 1} hold for $\vartheta=1$. We next show that with $y_0=e^{\tau_0}$, \eqref{V} holds for $\mu=\frac34$ and $\mu\in(\frac34,1)$. The case $\mu\in(\frac34,1)$ is treated analogously to the first case by noting that $3-4\mu<0$.  When $\mu=\frac34$, for $\tau_0$ sufficiently large, we have
 \begin{equation}
        V = C\int_{\tau_0}^\tau e^{-\frac34\tau'}\sqrt{\ln 2+\tau'}\ dy \leq   C\int_{\tau_0}^\tau e^{-\frac12\tau}\ dy \leq \frac14 B.
 \end{equation}
This completes the proof.

\label{hardy 1}
	Let $n\in \mathbb N_{\geq 3}$ and $\mathtt a>0$. Consider the function $f\in H^n([0,\infty))$ satisfies $f(0)=\partial_yf(0)=\dots=\partial_y^{n-1}f(0)=0$. Then, for any $i\in\{0,\dots,n-1\}$, we have
	\begin{equation}\label{5.1}
		\left\lVerty^{-(n-i)} \partial_y^i f\right\rVert_{L^2([0, \infty))} \leq  A\left\lVert\partial_y^n f\right\rVert_{L^2([0, \infty))}
	\end{equation}
	where $A$ is a positive constant.

Direct computation shows that for $ f\in H^n([0,\infty))$ with $f(0)=\partial_yf(0)=\dots=\partial_y^{n-1}f(0)=0$,
    \begin{align*}
        \int_0^\infty \frac{(\partial_y^i f)^2}{y^{2(n-i)}} dy =- \int_0^\infty \frac{(\partial_y^i f)^2}{y^{2(n-i-1)}} (\frac{1}{y})' dy = \int_0^\infty \frac{2\partial_y^i f\partial_y^{i+1} f}{y^{2(n-i-1)+1}}  dy -2(n-i-1)  \int_0^\infty \frac{(\partial_y^i f)^2}{y^{2(n-i)}} dy.
    \end{align*}
    Hence,
    \begin{align*}
        (n-i-\frac12)  \int_0^\infty \frac{(\partial_y^i f)^2}{y^{2(n-i)}} dy = \int_0^\infty \frac{\partial_y^i f\partial_y^{i+1} f}{y^{2(n-i-1)+1}}  dy \ \ \Rightarrow \ \  \left\lVert\frac{\partial_y^i f}{y^{n-i}}\right\rVert_{L^2([0,\infty))} \leq A \left\lVert\frac{\partial_y^{i+1} f}{y^{n-i-1}}\right\rVert_{L^2([0,\infty))}. 
    \end{align*}  
    Iterating this estimate for $i,i+1,\dots,n-1$ gives \eqref{5.1}.

\label{G-N with weight}
	Let $n\in \mathbb N_{\geq 2}$.  
    Consider the function $f\in H^n([0,\infty))$ satisfies $f(0)=\partial_yf(0)=\dots=\partial_y^{n-1}f(0)=0$. Then, for any $i\in\{1,\dots,n-1\}$ and $y_*>0$, we have
	\begin{equation}
		\left\lVerty^{i-n} \partial_y^i f\right\rVert_{L^2([y_*, \infty))} \leq C_* \left\lVerty^{-n}f\right\rVert_{L^2}^{1-\theta} \left\lVert\partial_y^n f\right\rVert_{L^2}^{\theta} 
	\end{equation}
	where $\theta=\frac{i}{n}$, and $C_*:=C_*(y_*)$ is a positive constant.

\label{Linfty decay}
	Let $f \in\dot H^1([0,\infty)) \cap \dot H^n([0,\infty))$. Suppose $\partial_y ^j f(0) =0$ for some $j\in\{1,\dots, n-1\}$. Then, 
	\begin{equation}
		\left\lVert\partial_y^j f\right\rVert_{L^\infty} \lesssim \left\lVert\partial_y f\right\rVert_{L^2}^{1-\frac{2j-1}{2(n-1)}} \left\lVert\partial_y^n f\right\rVert_{L^2}^{\frac{2j-1}{2(n-1)}}. 
	\end{equation}

\label{trivial mode}
    Let $\gamma\in(1,3)$ and $\mu\in[\frac12,1)$.                                
    The unstable spectrum consisting of non-positive eigenvalues of $\mathcal L$                                     
    on the H\"{o}lder continuous functions $C^{[\frac{1}{1-\mu}], \frac{1}{1-\mu} - [\frac{1}{1-\mu}]}             
    $ is given by                                      
    \begin{equation}\notag 
            \mathfrak R(\mathcal L) = 
            \begin{cases}
            \{j (1-\mu)-1 \ | \ j\in \mathbb{N}_{\ge 0}\cap [0,\frac{1}{1-\mu} ]  \}, & \text{if } \mu \in \mathfrak S  \\                  
            \{j (1-\mu)-1 \ | \ j\in \mathbb{N} \cap [1, \lfloor\frac{1}{1-\mu}\rfloor ] \} \cup \{0\}, & \text{if } \mu \notin \mathfrak S 
            \end{cases}
    \end{equation}
    The eigenfunctions related to symmetries are 
    \begin{equation}\label{5.17}
         \mathcal L(\Lambda_{x_0} \bar z) = -(\Lambda_{x_0} \bar z),\ \ \mathcal L(\Lambda_{T} \bar z) = -\mu (\Lambda_{T} \bar z),\ \  \mathcal L(\Lambda_{v} \bar z) = - (1-\mu)\Lambda_{v} \bar z,\ \ \mathcal L(\Lambda_\alpha \bar z)=0. 
    \end{equation} 
    Moreover, these eigenfunctions are given by
    \begin{align}\label{eigenfunction}
        \mathcal L(\phi_a) = a \phi_a,\qquad \phi_a = \frac{(-\bar z)^{\frac{1+a}{1-\mu}}}{1-\mu+(-\bar z )^{\frac{\mu}{1-\mu}}}\text{ with } a \in \mathfrak R(\mathcal L).
    \end{align}

We first recall \eqref{B formula}. By rewriting $y =K \frac{(\frac{2\mu}{1+\gamma}-\bar U)^{\frac1\mu -1}}{ \bar U ^\frac1\mu}$ 
and taking $K=\frac12$, we obtain
\begin{equation}
    \frac{4\mu}{1+\gamma} y = -\bar z +(-\bar z)^{\frac{1}{1-\mu}}.
\end{equation}

Consider the eigenvalue problem $ \mathcal L(\phi_a) = a \phi_a$ and we may derive 
\begin{align*}
    \frac{d\phi_a}{d\bar z} = \phi_a \frac{-(a+1)-(\frac{a}{1-\mu}+1)(-\bar z)^{\frac{\mu}{1-\mu}}}{(\mu-1)\bar z +(-\bar z)^\frac{1}{1-\mu}}.
\end{align*}
It then follows that
\begin{equation}
    \phi_a \in \text{Span}\{\frac{(-\bar z)^{\frac{1+a}{1-\mu}}}{1-\mu+(-\bar z )^{\frac{\mu}{1-\mu}}}\}.
\end{equation}
Let $a\le 0$ be given. In order for $\phi_a$ to be $\frac{1}{1-\mu}$-H\"{o}lder continuous, we have that $1+a = j (1-\mu)$ for $0\le j \le \frac{1}{1-\mu}$ and $j\in \mathbb N_{\ge 0}$. If  $\frac{1}{1-\mu}$ is an integer, the eigenfunctions are smooth and the unstable spectrum is given by $\{  -1 + j (1-\mu) : 0 \le j \le \frac{1}{1-\mu}  \}$.  
If $\frac{1}{1-\mu}$ is not an integer, $\phi_{-1}$ is only $\frac{\mu}{1-\mu}$-H\"{o}lder continuous. the unstable part of the spectrum is given by $\{  -1 + j (1-\mu) : 1 \le j \le [\frac{1}{1-\mu}] \}\cup \{0\}$.

